css:
@page { size: 80mm auto; margin: 0; }
.print-format { width: 72mm; padding: 2mm; font-family: monospace; font-size: 13px; }
.kot .unit { text-align: center; font-weight: bold; font-size: 15px; text-transform: uppercase; }
.kot .banner { text-align: center; font-weight: bold; font-size: 16px; margin: 2mm 0; padding: 1mm 0; border-top: 2px solid #000; border-bottom: 2px solid #000; }
.kot .banner-cancel { background: #000; color: #fff; }
.kot .order-no { text-align: center; font-size: 22px; font-weight: bold; margin: 1mm 0; }
.kot table { width: 100%; border-collapse: collapse; }
.kot .meta td { padding: 0.5mm 0; vertical-align: top; }
.kot .meta td:first-child { width: 20mm; }
.kot .meta .big { font-size: 16px; font-weight: bold; }
.kot .items { margin-top: 2mm; border-top: 1px dashed #000; }
.kot .items td { padding: 1mm 0; vertical-align: top; border-bottom: 1px dashed #ccc; }
.kot .items .qty { width: 10mm; font-weight: bold; font-size: 15px; }
.kot .items .item td { font-size: 14px; }
.kot .items .addon td { padding-left: 2mm; font-size: 12px; }
.kot .was { font-size: 11px; }
.kot .note { font-size: 12px; font-style: italic; }
.kot .comments { margin-top: 2mm; padding-top: 1mm; border-top: 1px dashed #000; font-size: 12px; }

html:
{%- macro q(v) -%}{%- set f = frappe.utils.flt(v) -%}{{ f|int if f == f|int else f }}{%- endmacro -%}
{%- set kot_type = doc.kot_type or "New Order" -%}
{%- set is_cancel = kot_type in ("Cancelled", "Partially Cancelled") -%}
{%- set banners = {
	"Cancelled": "*** CANCELLED ***",
	"Partially Cancelled": "*** PARTIAL CANCEL ***",
	"Duplicate": "*** DUPLICATE ***",
	"Transfer": "*** TRANSFER ***",
	"Modified": "MODIFIED",
} -%}
<div class="kot">
	<div class="unit">{{ doc.production_unit or "" }}</div>
	{% if banners.get(kot_type) %}
	<div class="banner {{ 'banner-cancel' if is_cancel else '' }}">{{ banners.get(kot_type) }}</div>
	{% endif %}
	{% if doc.daily_order_no %}
	<div class="order-no">#{{ doc.daily_order_no }}</div>
	{% endif %}
	<table class="meta">
		<tr><td>KOT</td><td>{{ doc.name }}</td></tr>
		{% if kot_type == "Duplicate" and doc.original_kot %}
		<tr><td>Copy of</td><td>{{ doc.original_kot }}</td></tr>
		{% endif %}
		{% if doc.table %}
		<tr><td>Table</td><td class="big">{{ doc.table }}</td></tr>
		{% endif %}
		<tr><td>Type</td><td>{{ doc.order_type or "Dine In" }}</td></tr>
		{% if doc.customer_name %}
		<tr><td>Customer</td><td>{{ doc.customer_name }}</td></tr>
		{% endif %}
		{% if doc.user %}
		<tr><td>By</td><td>{{ frappe.db.get_value("User", doc.user, "full_name") or doc.user }}</td></tr>
		{% endif %}
		<tr><td>Time</td><td>{{ frappe.utils.format_datetime(doc.creation, "dd/MM HH:mm") }}</td></tr>
	</table>
	<table class="items">
		{% for item in doc.items %}
		{%- set old = item.old_qty or 0 -%}
		{%- set cancelled = (old - item.qty) if old > item.qty else 0 -%}
		<tr class="{{ 'addon' if item.is_addon else 'item' }}">
			<td class="qty">
				{%- if is_cancel or (old and not item.qty) -%}
					-{{ q(item.cancelled_qty or cancelled) }}
				{%- else -%}
					{{ q(item.qty) }}
				{%- endif -%}
			</td>
			<td>
				{{ "+ " if item.is_addon else "" }}{{ item.item_name or item.item }}
				{% if not is_cancel and old and not item.qty %}
				<span class="was">(removed)</span>
				{% elif not is_cancel and kot_type != "Duplicate" and old and old != item.qty %}
				<span class="was">(was {{ q(old) }})</span>
				{% endif %}
				{% if item.comments %}<div class="note">&raquo; {{ item.comments }}</div>{% endif %}
			</td>
		</tr>
		{% endfor %}
	</table>
	{% if doc.comments %}
	<div class="comments">{{ doc.comments }}</div>
	{% endif %}
</div>
